package com.itsm.changemanagement.entity;
import jakarta.persistence.*;import java.time.*;

/**
 * JPA entity representing a Change Request (RFC) in {@code change_requests}.
 *
 * <p><b>Purpose:</b> Central ITIL Change Management entity encapsulating all request details: unique change number
 * (CHG-XXXXXXXX), requester info, change type/category/priority/risk, business justifications,
 * implementation/rollback/test plans, scheduled windows, CAB reviews and approvals, progress tracking,
 * post-validation results, rollback actions, PIR notes, and custom dynamic form values.
 *
 * <p><b>Downstream / Workflow:</b> Persisted and manipulated by {@link com.itsm.changemanagement.service.ChangeService}
 * through repository {@link com.itsm.changemanagement.repository.ChangeRequestRepository}.
 */
@Entity @Table(name="change_requests", uniqueConstraints=@UniqueConstraint(columnNames="change_number"))
public class ChangeRequest {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;
 @Column(name="change_number",nullable=false,unique=true) private String changeNumber;
 @Column(nullable=false,length=180) private String shortDescription;
 @Column(nullable=false,columnDefinition="TEXT") private String detailedDescription;
 @Column(nullable=false) private String requestedBy; @Column(nullable=false) private String requesterEmail; @Column(nullable=false) private String department;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private ChangeType changeType;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private ChangeCategory category;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private Priority priority;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private RiskLevel riskLevel;
 @Column(columnDefinition="TEXT") private String impact; private String affectedCi;
 @Column(columnDefinition="TEXT") private String businessJustification; @Column(columnDefinition="TEXT") private String implementationPlan; @Column(columnDefinition="TEXT") private String rollbackPlan; @Column(columnDefinition="TEXT") private String testPlan;
 private LocalDateTime plannedStartDate; private LocalDateTime plannedEndDate;
 @Enumerated(EnumType.STRING) @Column(nullable=false) private ChangeStatus status=ChangeStatus.DRAFT;
 @Column(columnDefinition="TEXT") private String riskDescription; @Column(columnDefinition="TEXT") private String businessImpact; @Column(columnDefinition="TEXT") private String technicalImpact; private Boolean serviceDowntimeExpected=false; @Column(columnDefinition="TEXT") private String riskMitigationPlan;
 private String assignedAnalyst;private String technicalTeam;private String implementationTeam;private String changeManager;private LocalDateTime assignedAt;
 private String reviewer;private String reviewComments;private LocalDateTime reviewedAt;
 private String approvedBy;private String approvalComments;private LocalDateTime approvedAt;private String emergencyJustification;
 private String maintenanceWindow;private String scheduledBy;private LocalDateTime scheduledAt;
 private Integer implementationProgress=0;private String implementationNotes;private LocalDateTime implementationStartedAt;private LocalDateTime implementationEndedAt;private String implementationOutcome;
 private String testResults;private String testerName;private LocalDateTime testingDate;private String validationComments;@Enumerated(EnumType.STRING) private ValidationStatus validationStatus=ValidationStatus.PENDING;
 private Boolean rollbackRequired=false;private String rollbackReason;private String rollbackNotes;private LocalDateTime rollbackStartedAt;private LocalDateTime rollbackCompletedAt;private String rollbackStatus;
 private String closureNotes;private String closedBy;private LocalDateTime closedDate;private String finalOutcome;private String postImplementationReview;
 private String cancellationReason;private String cancelledBy;private LocalDateTime cancelledAt;
 @Column(columnDefinition="longtext") private String customValues="{}";
 private LocalDateTime createdAt;private LocalDateTime updatedAt;
 @PrePersist void create(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getChangeNumber(){return changeNumber;}public void setChangeNumber(String v){changeNumber=v;} public String getShortDescription(){return shortDescription;}public void setShortDescription(String v){shortDescription=v;} public String getDetailedDescription(){return detailedDescription;}public void setDetailedDescription(String v){detailedDescription=v;} public String getRequestedBy(){return requestedBy;}public void setRequestedBy(String v){requestedBy=v;} public String getRequesterEmail(){return requesterEmail;}public void setRequesterEmail(String v){requesterEmail=v;} public String getDepartment(){return department;}public void setDepartment(String v){department=v;} public ChangeType getChangeType(){return changeType;}public void setChangeType(ChangeType v){changeType=v;} public ChangeCategory getCategory(){return category;}public void setCategory(ChangeCategory v){category=v;} public Priority getPriority(){return priority;}public void setPriority(Priority v){priority=v;} public RiskLevel getRiskLevel(){return riskLevel;}public void setRiskLevel(RiskLevel v){riskLevel=v;} public String getImpact(){return impact;}public void setImpact(String v){impact=v;} public String getAffectedCi(){return affectedCi;}public void setAffectedCi(String v){affectedCi=v;} public String getBusinessJustification(){return businessJustification;}public void setBusinessJustification(String v){businessJustification=v;} public String getImplementationPlan(){return implementationPlan;}public void setImplementationPlan(String v){implementationPlan=v;} public String getRollbackPlan(){return rollbackPlan;}public void setRollbackPlan(String v){rollbackPlan=v;} public String getTestPlan(){return testPlan;}public void setTestPlan(String v){testPlan=v;} public LocalDateTime getPlannedStartDate(){return plannedStartDate;}public void setPlannedStartDate(LocalDateTime v){plannedStartDate=v;} public LocalDateTime getPlannedEndDate(){return plannedEndDate;}public void setPlannedEndDate(LocalDateTime v){plannedEndDate=v;} public ChangeStatus getStatus(){return status;}public void setStatus(ChangeStatus v){status=v;} public String getRiskDescription(){return riskDescription;}public void setRiskDescription(String v){riskDescription=v;} public String getBusinessImpact(){return businessImpact;}public void setBusinessImpact(String v){businessImpact=v;} public String getTechnicalImpact(){return technicalImpact;}public void setTechnicalImpact(String v){technicalImpact=v;} public Boolean getServiceDowntimeExpected(){return serviceDowntimeExpected;}public void setServiceDowntimeExpected(Boolean v){serviceDowntimeExpected=v;} public String getRiskMitigationPlan(){return riskMitigationPlan;}public void setRiskMitigationPlan(String v){riskMitigationPlan=v;} public String getAssignedAnalyst(){return assignedAnalyst;}public void setAssignedAnalyst(String v){assignedAnalyst=v;} public String getTechnicalTeam(){return technicalTeam;}public void setTechnicalTeam(String v){technicalTeam=v;} public String getImplementationTeam(){return implementationTeam;}public void setImplementationTeam(String v){implementationTeam=v;} public String getChangeManager(){return changeManager;}public void setChangeManager(String v){changeManager=v;} public LocalDateTime getAssignedAt(){return assignedAt;}public void setAssignedAt(LocalDateTime v){assignedAt=v;} public String getReviewer(){return reviewer;}public void setReviewer(String v){reviewer=v;}public void setReviewComments(String v){reviewComments=v;}public String getReviewComments(){return reviewComments;}public void setReviewedAt(LocalDateTime v){reviewedAt=v;}public LocalDateTime getReviewedAt(){return reviewedAt;} public String getApprovedBy(){return approvedBy;}public void setApprovedBy(String v){approvedBy=v;}public String getApprovalComments(){return approvalComments;}public void setApprovalComments(String v){approvalComments=v;}public LocalDateTime getApprovedAt(){return approvedAt;}public void setApprovedAt(LocalDateTime v){approvedAt=v;}public String getEmergencyJustification(){return emergencyJustification;}public void setEmergencyJustification(String v){emergencyJustification=v;} public String getMaintenanceWindow(){return maintenanceWindow;}public void setMaintenanceWindow(String v){maintenanceWindow=v;}public String getScheduledBy(){return scheduledBy;}public void setScheduledBy(String v){scheduledBy=v;}public LocalDateTime getScheduledAt(){return scheduledAt;}public void setScheduledAt(LocalDateTime v){scheduledAt=v;} public Integer getImplementationProgress(){return implementationProgress;}public void setImplementationProgress(Integer v){implementationProgress=v;}public String getImplementationNotes(){return implementationNotes;}public void setImplementationNotes(String v){implementationNotes=v;}public LocalDateTime getImplementationStartedAt(){return implementationStartedAt;}public void setImplementationStartedAt(LocalDateTime v){implementationStartedAt=v;}public LocalDateTime getImplementationEndedAt(){return implementationEndedAt;}public void setImplementationEndedAt(LocalDateTime v){implementationEndedAt=v;}public String getImplementationOutcome(){return implementationOutcome;}public void setImplementationOutcome(String v){implementationOutcome=v;} public String getTestResults(){return testResults;}public void setTestResults(String v){testResults=v;}public String getTesterName(){return testerName;}public void setTesterName(String v){testerName=v;}public LocalDateTime getTestingDate(){return testingDate;}public void setTestingDate(LocalDateTime v){testingDate=v;}public String getValidationComments(){return validationComments;}public void setValidationComments(String v){validationComments=v;}public ValidationStatus getValidationStatus(){return validationStatus;}public void setValidationStatus(ValidationStatus v){validationStatus=v;} public Boolean getRollbackRequired(){return rollbackRequired;}public void setRollbackRequired(Boolean v){rollbackRequired=v;}public String getRollbackReason(){return rollbackReason;}public void setRollbackReason(String v){rollbackReason=v;}public String getRollbackNotes(){return rollbackNotes;}public void setRollbackNotes(String v){rollbackNotes=v;}public LocalDateTime getRollbackStartedAt(){return rollbackStartedAt;}public void setRollbackStartedAt(LocalDateTime v){rollbackStartedAt=v;}public LocalDateTime getRollbackCompletedAt(){return rollbackCompletedAt;}public void setRollbackCompletedAt(LocalDateTime v){rollbackCompletedAt=v;}public String getRollbackStatus(){return rollbackStatus;}public void setRollbackStatus(String v){rollbackStatus=v;} public String getClosureNotes(){return closureNotes;}public void setClosureNotes(String v){closureNotes=v;}public String getClosedBy(){return closedBy;}public void setClosedBy(String v){closedBy=v;}public LocalDateTime getClosedDate(){return closedDate;}public void setClosedDate(LocalDateTime v){closedDate=v;}public String getFinalOutcome(){return finalOutcome;}public void setFinalOutcome(String v){finalOutcome=v;}public String getPostImplementationReview(){return postImplementationReview;}public void setPostImplementationReview(String v){postImplementationReview=v;} public String getCancellationReason(){return cancellationReason;}public void setCancellationReason(String v){cancellationReason=v;}public String getCancelledBy(){return cancelledBy;}public void setCancelledBy(String v){cancelledBy=v;}public LocalDateTime getCancelledAt(){return cancelledAt;}public void setCancelledAt(LocalDateTime v){cancelledAt=v;} public String getCustomValues(){return customValues;}public void setCustomValues(String v){customValues=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getUpdatedAt(){return updatedAt;}
}
